function exportCsv(titles: Title[]) { const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob(["\ufeffNuméro;Conservation;Série;Box;Statut;Cadastre\n" + titles.map(t => [t.number,t.category,t.number[0],t.box,t.status,t.cadastre || ""].map(v => `"${v.replaceAll('"', '""')}"`).join(";")).join("\n")], { type: "text/csv;charset=utf-8" })); a.download = "fonciarch-titres.csv"; a.click(); URL.revokeObjectURL(a.href); }

