      const ni = headers.indexOf("numero"), ci = headers.includes("conservation") ? headers.indexOf("conservation") : headers.indexOf("categorie"), bi = headers.indexOf("box"), si = headers.indexOf("statut"), di = headers.indexOf("cadastre");
      if (headers.includes("conservation") && headers.includes("categorie")) throw new Error("Gardez une seule colonne Conservation ; retirez l’ancienne colonne Catégorie.");
      if (new Set(headers).size !== headers.length) throw new Error("Chaque nom de colonne doit apparaître une seule fois.");
